import Link from "next/link";
import type { AdminUserDto } from "@/lib/admin/queries";
import { dateLabel } from "./common";
export function UsersTable({ users }: { users: AdminUserDto[] }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-left text-sm">
        <caption className="sr-only">User accounts and current access</caption>
        <thead>
          <tr>
            {[
              "User",
              "Plan",
              "Subscription",
              "Account",
              "Last active",
              "Monthly usage",
            ].map((s) => (
              <th
                key={s}
                scope="col"
                className="border-b border-dotted border-separator p-3"
              >
                {s}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {users.map((u) => (
            <tr key={u.id} className="border-b border-dotted border-separator">
              <td className="p-3">
                <Link className="underline" href={`/admin/users/${u.id}`}>
                  {u.name || u.email}
                </Link>
                <div>{u.email}</div>
                <div className="text-xs text-body">
                  Joined {dateLabel(u.createdAt)}
                </div>
              </td>
              <td className="p-3">
                {u.effectivePlan}
                <div className="text-body">Base {u.plan}</div>
                {u.planOverride && <div>Override {u.planOverride}</div>}
              </td>
              <td className="p-3">{u.subscriptionStatus}</td>
              <td className="p-3">
                {u.isSuspended ? "Suspended" : "Active"}
                {u.deletionPending && <div>Deletion pending</div>}
                {u.reconnectRequired && <div>Gmail reconnect required</div>}
              </td>
              <td className="p-3">{dateLabel(u.lastActiveAt)}</td>
              <td className="p-3">
                {u.usage.monthly ? (
                  <>
                    {u.usage.monthly.sent} sent · {u.usage.monthly.reserved}{" "}
                    reserved<div>{u.usage.monthly.remaining} remaining</div>
                    <div className="text-body">{u.usage.monthly.label}</div>
                  </>
                ) : (
                  u.usage.state
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {!users.length && <p className="py-6">No users match these filters.</p>}
    </div>
  );
}
